export const QUESTIONS = [{"id":"ox-retrovirus-019","lecture":"retrovirus","topic":"4세대 선별","statement":"HIV 4세대 검사는 항체와 p24 항원을 함께 검출한다.","answer":true,"explanation":"감염 초기 검출에 도움이 된다.","pages":[12],"order":1069},{"id":"ox-retrovirus-020","lecture":"retrovirus","topic":"윈도기","statement":"노출 직후 선별검사 음성이면 이후 HIV 감염 가능성은 완전히 없다.","answer":false,"explanation":"검출 전 윈도기를 고려해야 한다.","pages":[12],"order":1070},{"id":"ox-retrovirus-021","lecture":"retrovirus","topic":"확인 검사","statement":"HIV 선별 양성은 권장 알고리즘에 따라 추가 확인한다.","answer":true,"explanation":"선별과 확진을 구분한다.","pages":[12],"order":1071},{"id":"ox-retrovirus-022","lecture":"retrovirus","topic":"병합 ART","statement":"ART는 바이러스 생활사의 서로 다른 표적에 작용하는 약제를 병합한다.","answer":true,"explanation":"억제 효과와 내성 예방을 고려한다.","pages":[13],"order":1072},{"id":"ox-retrovirus-023","lecture":"retrovirus","topic":"완치","statement":"ART로 바이러스량이 검출한계 미만이면 잠복 유전체까지 모두 제거된 것이다.","answer":false,"explanation":"바이러스 억제와 완전 제거는 다르다.","pages":[13],"order":1073},{"id":"ox-retrovirus-024","lecture":"retrovirus","topic":"치료 지속","statement":"HIV 치료의 지속적인 복용은 바이러스 억제 유지에 중요하다.","answer":true,"explanation":"중단 시 재상승과 내성 문제를 고려한다.","pages":[13],"order":1074},{"id":"ox-retrovirus-025","lecture":"retrovirus","topic":"PrEP","statement":"PrEP는 이미 확진된 HIV 감염을 치료하는 단독요법의 이름이다.","answer":false,"explanation":"노출 전 예방이며 확진 감염의 ART와 다르다.","pages":[10,13],"order":1075},{"id":"ox-retrovirus-026","lecture":"retrovirus","topic":"HTLV-1","statement":"HTLV-1은 성인 T세포백혈병·림프종과 관련된다.","answer":true,"explanation":"HIV와 대표 질환이 다르다.","pages":[16],"order":1076},{"id":"ox-retrovirus-027","lecture":"retrovirus","topic":"척수병증","statement":"HTLV-1은 열대성 경직성 하반신마비와 관련될 수 있다.","answer":true,"explanation":"종양만 일으키는 바이러스는 아니다.","pages":[16],"order":1077},{"id":"ox-retrovirus-028","lecture":"retrovirus","topic":"HTLV 경과","statement":"HTLV-1 감염자는 모두 수주 안에 백혈병으로 진행한다.","answer":false,"explanation":"많은 감염자는 무증상이며 일부에서 긴 잠복기 후 발병한다.","pages":[16],"order":1078},{"id":"ox-retrovirus-029","lecture":"retrovirus","topic":"HTLV 전파","statement":"HTLV-1은 수유·성접촉·혈액을 통해 전파될 수 있다.","answer":true,"explanation":"감염된 세포의 전달이 중요하다.","pages":[16],"order":1079},{"id":"ox-retrovirus-030","lecture":"retrovirus","topic":"두 바이러스 비교","statement":"HIV와 HTLV-1은 대표적으로 같은 기전의 CD4 고갈만을 일으킨다.","answer":false,"explanation":"HIV의 면역결핍과 HTLV-1의 증식성·염증성 질환을 구분한다.","pages":[17],"order":1080},{"id":"ox-rhabdovirus-slow-viruses-001","lecture":"rhabdovirus-slow-viruses","topic":"광견병 구조","statement":"광견병바이러스는 외피를 가진 음성가닥 RNA 바이러스이다.","answer":true,"explanation":"특징적인 탄환 모양 입자를 가진다.","pages":[3,6],"order":1081},{"id":"ox-rhabdovirus-slow-viruses-002","lecture":"rhabdovirus-slow-viruses","topic":"유전체","statement":"광견병바이러스는 원형 이중가닥 DNA를 가진다.","answer":false,"explanation":"비분절 음성가닥 RNA이다.","pages":[6],"order":1082},{"id":"ox-rhabdovirus-slow-viruses-003","lecture":"rhabdovirus-slow-viruses","topic":"진입 단백질","statement":"광견병바이러스의 G 단백질은 숙주 세포 결합·진입에 중요하다.","answer":true,"explanation":"중화항체의 표적이기도 하다.","pages":[7],"order":1083},{"id":"ox-rhabdovirus-slow-viruses-004","lecture":"rhabdovirus-slow-viruses","topic":"노출 경로","statement":"감염 동물의 타액이 상처나 점막에 닿으면 광견병 노출이 될 수 있다.","answer":true,"explanation":"피부가 온전한 단순 접촉과 구분한다.","pages":[8],"order":1084},{"id":"ox-rhabdovirus-slow-viruses-005","lecture":"rhabdovirus-slow-viruses","topic":"초기 확산","statement":"광견병바이러스는 주로 혈액 안에서 대량 증식해 뇌에 도달한다.","answer":false,"explanation":"말초신경을 따라 중추신경계로 이동하는 경로가 중요하다.","pages":[8],"order":1085},{"id":"ox-rhabdovirus-slow-viruses-006","lecture":"rhabdovirus-slow-viruses","topic":"신경 이동","statement":"광견병바이러스는 신경의 역행성 축삭 이동을 이용할 수 있다.","answer":true,"explanation":"교상 부위와 잠복기 등을 연결한다.","pages":[8,9],"order":1086},{"id":"ox-rhabdovirus-slow-viruses-007","lecture":"rhabdovirus-slow-viruses","topic":"잠복기","statement":"광견병의 잠복기는 모든 환자에서 정확히 하루이다.","answer":false,"explanation":"상처 위치·노출량 등에 따라 달라질 수 있다.","pages":[10],"order":1087},{"id":"ox-rhabdovirus-slow-viruses-008","lecture":"rhabdovirus-slow-viruses","topic":"신경 증상","statement":"광견병은 공수·흥분형뿐 아니라 마비형으로도 나타날 수 있다.","answer":true,"explanation":"전형적 물 공포만으로 모든 환자를 설명하지 않는다.","pages":[10,11],"order":1088},{"id":"ox-rhabdovirus-slow-viruses-009","lecture":"rhabdovirus-slow-viruses","topic":"Negri body","statement":"Negri body는 광견병의 세포질 봉입체이다.","answer":true,"explanation":"핵 내 봉입체와 구분한다.","pages":[16],"order":1089},{"id":"ox-rhabdovirus-slow-viruses-010","lecture":"rhabdovirus-slow-viruses","topic":"진단 배제","statement":"Negri body를 못 찾으면 광견병을 완전히 배제한다.","answer":false,"explanation":"다른 검사와 임상·노출력을 함께 평가한다.","pages":[16],"order":1090},{"id":"ox-rhabdovirus-slow-viruses-011","lecture":"rhabdovirus-slow-viruses","topic":"상처 세척","statement":"광견병 위험 교상 후 충분한 상처 세척은 중요한 초기 조치이다.","answer":true,"explanation":"백신이나 면역글로불린을 대신하지는 않는다.","pages":[19,20],"order":1091},{"id":"ox-rhabdovirus-slow-viruses-012","lecture":"rhabdovirus-slow-viruses","topic":"증상 후 예방","statement":"광견병 예방접종은 신경 증상이 생길 때까지 기다려 시작한다.","answer":false,"explanation":"증상 전 적절한 노출 후 예방이 핵심이다.","pages":[20,22],"order":1092},{"id":"ox-rhabdovirus-slow-viruses-013","lecture":"rhabdovirus-slow-viruses","topic":"능동·수동 면역","statement":"고위험 미접종자 노출에서는 백신과 면역글로불린을 함께 고려한다.","answer":true,"explanation":"접종력·노출 등급에 따라 조치가 다르다.","pages":[22,23],"order":1093},{"id":"ox-rhabdovirus-slow-viruses-014","lecture":"rhabdovirus-slow-viruses","topic":"접종 완료자","statement":"예방접종 완료자도 노출 후에는 언제나 미접종자와 같은 면역글로불린을 투여한다.","answer":false,"explanation":"접종력에 따라 노출 후 처치가 달라진다.","pages":[22],"order":1094},{"id":"ox-rhabdovirus-slow-viruses-015","lecture":"rhabdovirus-slow-viruses","topic":"노출 분류","statement":"동물이 상처 없는 피부를 핥은 것과 깊은 교상은 같은 위험 등급이 아니다.","answer":true,"explanation":"피부·점막 손상과 접촉 종류를 구분한다.","pages":[23],"order":1095},{"id":"ox-rhabdovirus-slow-viruses-016","lecture":"rhabdovirus-slow-viruses","topic":"동물 관리","statement":"반려동물 예방접종과 야생동물 접촉 감소는 광견병 예방에 중요하다.","answer":true,"explanation":"사람 노출을 줄이는 전략이다.","pages":[19],"order":1096},{"id":"ox-rhabdovirus-slow-viruses-017","lecture":"rhabdovirus-slow-viruses","topic":"지발감염","statement":"지발성 감염은 모두 프리온에 의해서만 생긴다.","answer":false,"explanation":"통상적인 바이러스에 의한 지발성 질환도 있다.","pages":[26,29],"order":1097},{"id":"ox-rhabdovirus-slow-viruses-018","lecture":"rhabdovirus-slow-viruses","topic":"SSPE","statement":"홍역 뒤 수년 후 발생하는 SSPE는 지발성 바이러스 질환의 예이다.","answer":true,"explanation":"프리온 질환과 구별한다.","pages":[29],"order":1098},{"id":"ox-rhabdovirus-slow-viruses-019","lecture":"rhabdovirus-slow-viruses","topic":"프리온","statement":"프리온의 감염성은 잘못 접힌 단백질 구조와 관련된다.","answer":true,"explanation":"핵산 유전체가 필수인 바이러스와 다르다.","pages":[33],"order":1099},{"id":"ox-rhabdovirus-slow-viruses-020","lecture":"rhabdovirus-slow-viruses","topic":"핵산","statement":"프리온은 작은 RNA 분절을 필수 유전체로 가진다.","answer":false,"explanation":"핵산 없이 단백질의 구조 변화로 전파된다.","pages":[33],"order":1100},{"id":"ox-rhabdovirus-slow-viruses-021","lecture":"rhabdovirus-slow-viruses","topic":"구조 전환","statement":"이상 프리온은 정상 단백질의 비정상 구조 전환을 촉진할 수 있다.","answer":true,"explanation":"구조의 연쇄적 변화가 축적된다.","pages":[34,35],"order":1101},{"id":"ox-rhabdovirus-slow-viruses-022","lecture":"rhabdovirus-slow-viruses","topic":"단백질분해","statement":"비정상 프리온은 정상 단백질보다 언제나 단백질분해효소에 쉽게 제거된다.","answer":false,"explanation":"상대적 분해 저항성이 중요하다.","pages":[34],"order":1102},{"id":"ox-rhabdovirus-slow-viruses-023","lecture":"rhabdovirus-slow-viruses","topic":"CJD","statement":"산발성 CJD는 사람 프리온 질환의 중요한 유형이다.","answer":true,"explanation":"모든 CJD가 음식으로 전파되는 것은 아니다.","pages":[42,45],"order":1103},{"id":"ox-rhabdovirus-slow-viruses-024","lecture":"rhabdovirus-slow-viruses","topic":"경과","statement":"CJD는 전형적으로 수십 년간 변화가 없는 안정된 기억장애이다.","answer":false,"explanation":"빠르게 진행하는 치매·신경 증상이 단서이다.","pages":[45],"order":1104},{"id":"ox-rhabdovirus-slow-viruses-025","lecture":"rhabdovirus-slow-viruses","topic":"해면상 변화","statement":"프리온 질환에서는 뇌 조직의 해면상 변화가 보일 수 있다.","answer":true,"explanation":"다수의 공포가 생기는 조직 변화이다.","pages":[44],"order":1105},{"id":"ox-rhabdovirus-slow-viruses-026","lecture":"rhabdovirus-slow-viruses","topic":"쿠루","statement":"쿠루는 의식적 식인 관습과 관련된 프리온 질환이다.","answer":true,"explanation":"노출 양상과 질환을 연결한다.","pages":[43],"order":1106},{"id":"ox-rhabdovirus-slow-viruses-027","lecture":"rhabdovirus-slow-viruses","topic":"BSE 연관","statement":"변종 CJD는 BSE 노출과 관계가 없다.","answer":false,"explanation":"소해면상뇌병증과의 연관이 중요하다.","pages":[48,56],"order":1107},{"id":"ox-rhabdovirus-slow-viruses-028","lecture":"rhabdovirus-slow-viruses","topic":"유전성 질환","statement":"일부 프리온 질환은 PRNP 유전자 변이와 관련된다.","answer":true,"explanation":"후천성 감염만으로 발생하는 것은 아니다.","pages":[50],"order":1108},{"id":"ox-rhabdovirus-slow-viruses-029","lecture":"rhabdovirus-slow-viruses","topic":"일반 소독","statement":"일반적인 알코올 소독만으로 프리온은 항상 충분히 불활성화된다.","answer":false,"explanation":"표준 소독에 강해 별도의 처리 원칙이 필요하다.","pages":[51],"order":1109},{"id":"ox-rhabdovirus-slow-viruses-030","lecture":"rhabdovirus-slow-viruses","topic":"기구 처리","statement":"프리온 위험 조직·기구는 특별한 오염 제거 지침을 적용한다.","answer":true,"explanation":"일반 기구 재처리와 동일시하지 않는다.","pages":[52,53],"order":1110},{"id":"ox-emerging-infection-response-001","lecture":"emerging-infection-response","topic":"신종의 의미","statement":"신종감염병에는 새 병원체 외에 기존 감염의 새로운 지역 확산도 포함될 수 있다.","answer":true,"explanation":"발생 증가와 인식의 변화를 포함하는 개념이다.","pages":[3],"order":1111,"sourceRefs":[{"index":2,"pages":[4]}]},{"id":"ox-emerging-infection-response-002","lecture":"emerging-infection-response","topic":"재출현","statement":"재출현 감염병은 원인 미생물이 반드시 새로 진화한 감염병이다.","answer":false,"explanation":"기존 질환이 감소 후 다시 늘어나는 경우도 있다.","pages":[3],"order":1112,"sourceRefs":[{"index":2,"pages":[4]}]},{"id":"ox-emerging-infection-response-003","lecture":"emerging-infection-response","topic":"대비","statement":"낯선 감염병은 진단·치료·감염관리 준비 부족으로 큰 피해를 낼 수 있다.","answer":true,"explanation":"사전 대비가 필요한 이유이다.","pages":[4],"order":1113,"sourceRefs":[{"index":2,"pages":[5]}]},{"id":"ox-emerging-infection-response-004","lecture":"emerging-infection-response","topic":"출현 요인","statement":"인구·생태·기후·행동 변화가 감염병 출현에 함께 작용한다.","answer":true,"explanation":"하나의 원인만으로 설명하지 않는다.","pages":[5],"order":1114,"sourceRefs":[{"index":2,"pages":[6,42]}]},{"id":"ox-emerging-infection-response-005","lecture":"emerging-infection-response","topic":"동물 감염","statement":"동물 병원체가 사람 한 명을 감염시키면 사람 간 유행은 이미 확정이다.","answer":false,"explanation":"지속적인 사람 간 전파 능력을 추가로 확인한다.","pages":[9],"order":1115,"sourceRefs":[{"index":2,"pages":[10,11]}]},{"id":"ox-emerging-infection-response-006","lecture":"emerging-infection-response","topic":"토착화","statement":"감수성 숙주와 전파 조건은 감염병의 지속 정착에 중요하다.","answer":true,"explanation":"유입만으로 토착화가 보장되지 않는다.","pages":[10],"order":1116,"sourceRefs":[{"index":2,"pages":[11]}]},{"id":"ox-emerging-infection-response-007","lecture":"emerging-infection-response","topic":"재배열","statement":"분절 바이러스의 유전자 재배열은 새로운 조합을 만들 수 있다.","answer":true,"explanation":"인플루엔자 대유행 기전의 한 부분이다.","pages":[11],"order":1117,"sourceRefs":[{"index":2,"pages":[12,13]}]},{"id":"ox-emerging-infection-response-008","lecture":"emerging-infection-response","topic":"점돌연변이","statement":"한 염기의 점돌연변이와 RNA 분절 교환은 같은 과정이다.","answer":false,"explanation":"돌연변이와 reassortment를 구분한다.","pages":[11],"order":1118,"sourceRefs":[{"index":2,"pages":[12,13]}]},{"id":"ox-emerging-infection-response-009","lecture":"emerging-infection-response","topic":"에볼라 관리","statement":"에볼라 대응에는 감염성 체액 접촉을 줄이는 진료 체계가 중요하다.","answer":true,"explanation":"보호구·격리·안전한 처치를 함께 준비한다.","pages":[13],"order":1119,"sourceRefs":[{"index":2,"pages":[14,15,16]}]},{"id":"ox-emerging-infection-response-010","lecture":"emerging-infection-response","topic":"엠폭스","statement":"엠폭스는 특정 국적의 사람에게만 감염된다.","answer":false,"explanation":"감염성 접촉과 노출력을 중심으로 평가한다.","pages":[16,17],"order":1120,"sourceRefs":[{"index":2,"pages":[17,18]}]},{"id":"ox-emerging-infection-response-011","lecture":"emerging-infection-response","topic":"국제 이동","statement":"빠른 국제 이동은 감염병이 잠복기 중 국경을 넘게 할 수 있다.","answer":true,"explanation":"국경 조치만으로 모든 유입을 막기 어렵다.","pages":[18,19],"order":1121,"sourceRefs":[{"index":2,"pages":[19,21]}]},{"id":"ox-emerging-infection-response-012","lecture":"emerging-infection-response","topic":"검역 완전성","statement":"증상 선별 검역만으로 무증상·잠복기 감염을 모두 찾아낼 수 있다.","answer":false,"explanation":"검역에는 검출 한계가 있다.","pages":[20],"order":1122,"sourceRefs":[{"index":2,"pages":[19,21]}]},{"id":"ox-emerging-infection-response-013","lecture":"emerging-infection-response","topic":"국내 대응","statement":"유입 감염을 조기에 발견하고 국내 전파를 줄이는 체계가 필요하다.","answer":true,"explanation":"입국 단계 이후의 대응도 중요하다.","pages":[20],"order":1123,"sourceRefs":[{"index":2,"pages":[21,22,23]}]},{"id":"ox-emerging-infection-response-014","lecture":"emerging-infection-response","topic":"의료기관 전파","statement":"MERS 사례는 의료기관 내 전파 차단의 중요성을 보여준다.","answer":true,"explanation":"조기 인지와 적절한 주의 조치가 필요하다.","pages":[22],"order":1124,"sourceRefs":[{"index":2,"pages":[22,23]}]},{"id":"ox-emerging-infection-response-015","lecture":"emerging-infection-response","topic":"유행 원인","statement":"의료기관에서 환자가 늘어도 접촉 구조나 환경은 조사할 필요가 없다.","answer":false,"explanation":"환자 이동·접촉·진료 환경이 확산에 영향을 준다.","pages":[22],"order":1125,"sourceRefs":[{"index":2,"pages":[22,23]}]},{"id":"ox-emerging-infection-response-016","lecture":"emerging-infection-response","topic":"SFTS","statement":"국내 신종감염 대응에는 진드기 매개 SFTS도 포함된다.","answer":true,"explanation":"해외 유입 감염만 다루는 것은 아니다.","pages":[26,27],"order":1126,"sourceRefs":[{"index":2,"pages":[26,27,28]}]},{"id":"ox-emerging-infection-response-017","lecture":"emerging-infection-response","topic":"백신 유행","statement":"백신이 개발된 감염병은 접종률이 낮아져도 재유행할 수 없다.","answer":false,"explanation":"감수성 인구가 늘면 홍역 등도 재유행할 수 있다.","pages":[28],"order":1127,"sourceRefs":[{"index":2,"pages":[29]}]},{"id":"ox-emerging-infection-response-018","lecture":"emerging-infection-response","topic":"내성의 국제성","statement":"항생제 내성균은 국제 이동과 교역을 통해 확산될 수 있다.","answer":true,"explanation":"국가별로 완전히 분리된 문제가 아니다.","pages":[29,30],"order":1128,"sourceRefs":[{"index":2,"pages":[31,32]}]},{"id":"ox-emerging-infection-response-019","lecture":"emerging-infection-response","topic":"축산 항생제","statement":"동물 분야의 항생제 사용도 내성 문제와 연결된다.","answer":true,"explanation":"One Health 관점이 필요한 이유이다.","pages":[29],"order":1129,"sourceRefs":[{"index":2,"pages":[6,30]}]},{"id":"ox-emerging-infection-response-020","lecture":"emerging-infection-response","topic":"약제 개발","statement":"내성균 문제는 새 항생제가 나오면 감염관리 없이 영구 해결된다.","answer":false,"explanation":"약제 개발·적정 사용·전파 차단을 함께 해야 한다.","pages":[31],"order":1130,"sourceRefs":[{"index":2,"pages":[5,31,32,33]}]},{"id":"ox-emerging-infection-response-021","lecture":"emerging-infection-response","topic":"대응 인프라","statement":"감염병 전문병원은 중증 환자 진료와 격리 역량의 일부이다.","answer":true,"explanation":"시설뿐 아니라 운영 인력도 필요하다.","pages":[32],"order":1131,"sourceRefs":[{"index":2,"pages":[34]}]},{"id":"ox-emerging-infection-response-022","lecture":"emerging-infection-response","topic":"시설과 인력","statement":"격리 병상만 많이 만들면 훈련된 인력은 필요 없다.","answer":false,"explanation":"전문인력과 반복 훈련이 필수적이다.","pages":[32,33],"order":1132,"sourceRefs":[{"index":2,"pages":[34,35,41]}]},{"id":"ox-emerging-infection-response-023","lecture":"emerging-infection-response","topic":"훈련","statement":"비상 상황 전 교육과 훈련은 실제 감염병 대응을 돕는다.","answer":true,"explanation":"역할·절차·물자 운용을 점검한다.","pages":[33],"order":1133,"sourceRefs":[{"index":2,"pages":[35]}]},{"id":"ox-emerging-infection-response-024","lecture":"emerging-infection-response","topic":"국제 협력","statement":"IHR은 국제적인 감염병 감시·대응과 관련된다.","answer":true,"explanation":"국경을 넘는 위험을 공동 관리한다.","pages":[34],"order":1134,"sourceRefs":[{"index":2,"pages":[36]}]},{"id":"ox-emerging-infection-response-025","lecture":"emerging-infection-response","topic":"정보 공유","statement":"국외 발생 정보는 국내 대비와 무관하다.","answer":false,"explanation":"해외 유행 정보가 유입 위험과 준비에 중요하다.","pages":[34],"order":1135,"sourceRefs":[{"index":2,"pages":[19,36]}]},{"id":"ox-emerging-infection-response-026","lecture":"emerging-infection-response","topic":"인플루엔자 감시","statement":"국제 인플루엔자 감시는 변이 파악과 백신 선정에 활용된다.","answer":true,"explanation":"연속적인 검체·정보 공유가 필요하다.","pages":[36,37],"order":1136,"sourceRefs":[{"index":2,"pages":[38,39]}]},{"id":"ox-emerging-infection-response-027","lecture":"emerging-infection-response","topic":"유행 규모","statement":"계절 유행과 대유행은 같은 의미이므로 구분할 필요가 없다.","answer":false,"explanation":"전파 범위와 인구 면역·바이러스 변화가 다르다.","pages":[36],"order":1137,"sourceRefs":[{"index":2,"pages":[38,39]}]},{"id":"ox-emerging-infection-response-028","lecture":"emerging-infection-response","topic":"조기 탐지","statement":"병원체 감시와 진단 역량은 신종감염 조기 탐지에 중요하다.","answer":true,"explanation":"탐지 후 진료·공중보건 대응으로 연결해야 한다.","pages":[38],"order":1138,"sourceRefs":[{"index":2,"pages":[39,40]}]},{"id":"ox-emerging-infection-response-029","lecture":"emerging-infection-response","topic":"협력 체계","statement":"공공과 민간 의료기관의 역할 조정은 위기 대응에 필요하다.","answer":true,"explanation":"한 기관만으로 모든 환자와 전파를 다루기 어렵다.","pages":[39],"order":1139,"sourceRefs":[{"index":2,"pages":[34,35,36,37,38,39,40,41]}]},{"id":"ox-emerging-infection-response-030","lecture":"emerging-infection-response","topic":"대응 시점","statement":"새 감염병은 유행이 끝난 다음에만 대책을 세우는 것이 효과적이다.","answer":false,"explanation":"상시 대비·조기 탐지·즉각 대응이 중요하다.","pages":[40],"order":1140,"sourceRefs":[{"index":2,"pages":[41,42]}]},{"id":"ox-natural-history-surveillance-001","lecture":"natural-history-surveillance","topic":"감염과 증상","statement":"감염은 임상 증상이 뚜렷하지 않아도 성립할 수 있다.","answer":true,"explanation":"불현성 감염도 감시와 전파에 중요하다.","pages":[4],"order":1141,"sourceRefs":[{"index":2,"pages":[5]}]},{"id":"ox-natural-history-surveillance-002","lecture":"natural-history-surveillance","topic":"집락화","statement":"집락화란 미생물 검출과 동시에 조직 손상이 확정된 상태이다.","answer":false,"explanation":"미생물이 자리 잡았다는 뜻이며 임상 감염과 구별한다.","pages":[5],"order":1142,"sourceRefs":[{"index":2,"pages":[6]}]},{"id":"ox-natural-history-surveillance-003","lecture":"natural-history-surveillance","topic":"오염","statement":"검체 오염은 실제 감염 부위가 아닌 곳의 미생물이 섞인 상태일 수 있다.","answer":true,"explanation":"집락화·감염과 구별한다.","pages":[5],"order":1143,"sourceRefs":[{"index":2,"pages":[6]}]},{"id":"ox-natural-history-surveillance-004","lecture":"natural-history-surveillance","topic":"노출 시점","statement":"질환의 잠복기 분포는 공통 노출 시점을 추정하는 데 이용할 수 있다.","answer":true,"explanation":"환자들의 발병 시점에서 노출 기간을 거슬러 추정한다.","pages":[12],"order":1144,"sourceRefs":[{"index":2,"pages":[10,13]}]},{"id":"ox-natural-history-surveillance-005","lecture":"natural-history-surveillance","topic":"잠재기","statement":"역학적 잠재기는 증상 시작부터 회복까지의 기간이다.","answer":false,"explanation":"감염부터 전염력이 생기기까지의 기간이다.","pages":[9],"order":1145,"sourceRefs":[{"index":2,"pages":[8,9]}]},{"id":"ox-natural-history-surveillance-006","lecture":"natural-history-surveillance","topic":"원인 추정","statement":"노출 후 증상까지의 시간은 식중독 원인 추정에 도움이 된다.","answer":true,"explanation":"독소성 질환과 장내 증식 질환의 차이를 고려한다.","pages":[10,11],"order":1146,"sourceRefs":[{"index":2,"pages":[10,11]}]},{"id":"ox-natural-history-surveillance-007","lecture":"natural-history-surveillance","topic":"유행곡선","statement":"유행곡선의 가로축은 보통 환자의 혈압이다.","answer":false,"explanation":"보통 증상 발생 시각 또는 날짜이다.","pages":[12,13],"order":1147,"sourceRefs":[{"index":2,"pages":[13,14]}]},{"id":"ox-natural-history-surveillance-008","lecture":"natural-history-surveillance","topic":"공통 노출","statement":"단일 공통 매개 노출은 한 번의 노출 시점 뒤 환자가 몰릴 수 있다.","answer":true,"explanation":"잠복기 분포에 따른 곡선을 생각한다.","pages":[12],"order":1148,"sourceRefs":[{"index":2,"pages":[13]}]},{"id":"ox-natural-history-surveillance-009","lecture":"natural-history-surveillance","topic":"점진 전파","statement":"사람 간 연속 전파에서는 여러 세대의 환자가 이어질 수 있다.","answer":true,"explanation":"일회성 공통 노출과 비교한다.","pages":[13],"order":1149,"sourceRefs":[{"index":2,"pages":[14]}]},{"id":"ox-natural-history-surveillance-010","lecture":"natural-history-surveillance","topic":"격리 대상","statement":"격리는 원칙적으로 아직 감염 가능성이 없는 모든 일반인을 같은 방식으로 제한하는 것이다.","answer":false,"explanation":"감염자 등의 전파를 차단하는 조치와 노출자 관리를 구분한다.","pages":[15],"order":1150,"sourceRefs":[{"index":2,"pages":[16]}]},{"id":"ox-natural-history-surveillance-011","lecture":"natural-history-surveillance","topic":"SEIR","statement":"SEIR 모형의 S는 감수성 집단을 뜻한다.","answer":true,"explanation":"노출·감염성·회복 집단과 구분한다.","pages":[16],"order":1151,"sourceRefs":[{"index":2,"pages":[17]}]},{"id":"ox-natural-history-surveillance-012","lecture":"natural-history-surveillance","topic":"E 집단","statement":"SEIR에서 E 집단은 모두 즉시 다른 사람에게 전파하는 집단이다.","answer":false,"explanation":"노출 후 감염되었으나 아직 감염성이 없는 단계를 뜻한다.","pages":[16],"order":1152,"sourceRefs":[{"index":2,"pages":[17]}]},{"id":"ox-natural-history-surveillance-013","lecture":"natural-history-surveillance","topic":"감염력","statement":"감염력은 노출된 감수성자 중 감염되는 비율과 관련된다.","answer":true,"explanation":"감염자의 중증도 비율과 다르다.","pages":[17],"order":1153,"sourceRefs":[{"index":2,"pages":[18]}]},{"id":"ox-natural-history-surveillance-014","lecture":"natural-history-surveillance","topic":"병원성","statement":"병원성은 감염자 중 임상 질병이 발생하는 정도와 관련된다.","answer":true,"explanation":"노출자 전체 중 감염 여부와 구분한다.","pages":[17],"order":1154,"sourceRefs":[{"index":2,"pages":[18]}]},{"id":"ox-natural-history-surveillance-015","lecture":"natural-history-surveillance","topic":"독력","statement":"독력은 사람 사이 접촉 횟수만을 의미한다.","answer":false,"explanation":"질환의 중증도·사망 등과 관련된 개념이다.","pages":[17],"order":1155,"sourceRefs":[{"index":2,"pages":[18]}],"note":"필기본 확인: 자연사 PDF18쪽의 그림은 독력을 (D+E)/(B+C+D+E)로 제시합니다. C까지 합치는 다른 중증도 구분과 혼합하지 않습니다."},{"id":"ox-natural-history-surveillance-016","lecture":"natural-history-surveillance","topic":"발병률","statement":"유행 상황의 attack rate는 위험 집단 중 새로 발병한 비율이다.","answer":true,"explanation":"분모에 누가 포함되는지 확인한다.","pages":[18],"order":1156,"sourceRefs":[{"index":2,"pages":[18,19]}]},{"id":"ox-natural-history-surveillance-017","lecture":"natural-history-surveillance","topic":"치명률","statement":"치명률의 분모는 언제나 전체 지역 주민 수이다.","answer":false,"explanation":"해당 질환의 환자 수를 분모로 한다.","pages":[18],"order":1157,"sourceRefs":[{"index":2,"pages":[18]}]},{"id":"ox-natural-history-surveillance-018","lecture":"natural-history-surveillance","topic":"불현성 감염","statement":"증상 없는 감염자가 전파에 기여할 수 있다.","answer":true,"explanation":"현성 환자만 세면 감염 규모를 과소평가할 수 있다.","pages":[19],"order":1158,"sourceRefs":[{"index":2,"pages":[5,20]}]},{"id":"ox-natural-history-surveillance-019","lecture":"natural-history-surveillance","topic":"보균자","statement":"증상이 없어도 병원체를 지속 보유·배출하는 보균자가 있을 수 있다.","answer":true,"explanation":"장티푸스 만성 보균이 대표 예이다.","pages":[20],"order":1159,"sourceRefs":[{"index":2,"pages":[20,21]}]},{"id":"ox-natural-history-surveillance-020","lecture":"natural-history-surveillance","topic":"감염 사슬","statement":"감염 사슬에는 병원소와 침입구가 포함되지 않는다.","answer":false,"explanation":"병원체·병원소·탈출구·전파·침입구·숙주를 연결한다.","pages":[21],"order":1160,"sourceRefs":[{"index":2,"pages":[22]}]},{"id":"ox-natural-history-surveillance-021","lecture":"natural-history-surveillance","topic":"병원소","statement":"사람·동물·환경은 병원체에 따라 병원소가 될 수 있다.","answer":true,"explanation":"병원체별 자연 생태를 확인한다.","pages":[22],"order":1161,"sourceRefs":[{"index":2,"pages":[23]}]},{"id":"ox-natural-history-surveillance-022","lecture":"natural-history-surveillance","topic":"매개와 전파","statement":"오염 식수에 의한 전파와 모기 매개 전파는 같은 방식이다.","answer":false,"explanation":"공통 매개물과 생물학적 매개체를 구분한다.","pages":[23],"order":1162,"sourceRefs":[{"index":2,"pages":[24]}]},{"id":"ox-natural-history-surveillance-023","lecture":"natural-history-surveillance","topic":"One Health","statement":"인수공통감염 관리는 사람·동물·환경의 연결을 고려한다.","answer":true,"explanation":"부문 간 감시와 협력이 필요하다.","pages":[26],"order":1163,"sourceRefs":[{"index":2,"pages":[25]},{"index":3,"pages":[4]}]},{"id":"ox-natural-history-surveillance-024","lecture":"natural-history-surveillance","topic":"능동면역","statement":"예방접종은 숙주의 능동면역을 유도할 수 있다.","answer":true,"explanation":"항체를 직접 주는 수동면역과 구분한다.","pages":[27],"order":1164,"sourceRefs":[{"index":3,"pages":[5]}]},{"id":"ox-natural-history-surveillance-025","lecture":"natural-history-surveillance","topic":"수동면역","statement":"면역글로불린 투여는 숙주의 장기 면역 기억을 반드시 형성한다.","answer":false,"explanation":"즉각적인 수동 보호이며 지속 기간이 제한된다.","pages":[27],"order":1165,"sourceRefs":[{"index":3,"pages":[5]}]},{"id":"ox-natural-history-surveillance-026","lecture":"natural-history-surveillance","topic":"집단면역","statement":"다수의 면역은 감수성자의 병원체 노출을 간접적으로 줄일 수 있다.","answer":true,"explanation":"접촉 양상과 전파 특성에 따라 효과가 다르다.","pages":[28,30],"order":1166,"sourceRefs":[{"index":3,"pages":[6,7,8,9]}]},{"id":"ox-natural-history-surveillance-027","lecture":"natural-history-surveillance","topic":"R0","statement":"R0는 이미 방역과 면역이 충분한 현재 시점의 전파만을 뜻한다.","answer":false,"explanation":"감수성 집단에서의 기초 전파력을 나타내는 개념이다.","pages":[29],"order":1167,"sourceRefs":[{"index":3,"pages":[7]}]},{"id":"ox-natural-history-surveillance-028","lecture":"natural-history-surveillance","topic":"실효재생산수","statement":"실효재생산수는 면역·방역 등 현재 조건의 영향을 받는다.","answer":true,"explanation":"R0와 구분해 유행 상황을 평가한다.","pages":[29],"order":1168,"sourceRefs":[{"index":3,"pages":[7,8,9]}]},{"id":"ox-natural-history-surveillance-029","lecture":"natural-history-surveillance","topic":"유행 억제","statement":"실효재생산수가 1보다 크면 유행은 지속적으로 감소하는 것이 일반적이다.","answer":false,"explanation":"대체로 1 미만이어야 감소 방향을 기대한다.","pages":[31],"order":1169,"sourceRefs":[{"index":3,"pages":[7,8,9]}]},{"id":"ox-natural-history-surveillance-030","lecture":"natural-history-surveillance","topic":"면역과 전파","statement":"백신 효과와 접종률·접촉 구조는 집단 수준의 유행 억제에 영향을 준다.","answer":true,"explanation":"접종률 하나만으로 모든 상황을 설명하지 않는다.","pages":[30,31],"order":1170,"sourceRefs":[{"index":3,"pages":[6,7,8,9]}]},{"id":"ox-outbreak-investigation-001","lecture":"outbreak-investigation","topic":"R0","statement":"기초감염재생산수는 감수성 집단에서 환자 한 명이 만드는 평균 이차 감염 수와 관련된다.","answer":true,"explanation":"개별 환자가 반드시 그 수만큼 전파한다는 뜻은 아니다.","pages":[3],"order":1171,"sourceRefs":[{"index":2,"pages":[7]}]},{"id":"ox-outbreak-investigation-002","lecture":"outbreak-investigation","topic":"면역 역치","statement":"어떤 감염병이나 같은 접종률에서 동일하게 집단면역이 형성된다.","answer":false,"explanation":"전파력·백신 효과·접촉 구조에 따라 다르다.","pages":[4],"order":1172,"sourceRefs":[{"index":2,"pages":[6,7,8,9]}]},{"id":"ox-outbreak-investigation-003","lecture":"outbreak-investigation","topic":"유행 억제","statement":"면역을 높이거나 전파 접촉을 줄이면 실효재생산수를 낮출 수 있다.","answer":true,"explanation":"여러 방역 수단이 작용하는 원리이다.","pages":[5],"order":1173,"sourceRefs":[{"index":2,"pages":[7,8,9]}]},{"id":"ox-outbreak-investigation-004","lecture":"outbreak-investigation","topic":"대유행","statement":"Pandemic은 감염병의 넓은 지리적 확산을 뜻한다.","answer":true,"explanation":"개별 환자의 중증도와 같은 개념은 아니다.","pages":[6],"order":1174,"sourceRefs":[{"index":2,"pages":[10]}]},{"id":"ox-outbreak-investigation-005","lecture":"outbreak-investigation","topic":"풍토병","statement":"Endemic은 언제나 갑자기 전 세계로 퍼지는 유행을 뜻한다.","answer":false,"explanation":"지역에서 지속적으로 존재하는 상태이다.","pages":[6],"order":1175,"sourceRefs":[{"index":2,"pages":[10,11,16]}]},{"id":"ox-outbreak-investigation-006","lecture":"outbreak-investigation","topic":"연결성","statement":"사람들의 이동과 접촉망은 국가 간 감염 확산에 영향을 준다.","answer":true,"explanation":"행정 경계만으로 전파를 설명하지 않는다.","pages":[8,9],"order":1176,"sourceRefs":[{"index":2,"pages":[12,13]}]},{"id":"ox-outbreak-investigation-007","lecture":"outbreak-investigation","topic":"유행의 정의","statement":"환자가 두 명 이상이면 평소 수준과 무관하게 모두 같은 의미의 유행이다.","answer":false,"explanation":"특정 시간·장소·집단에서 기대 수준을 넘는지를 본다.","pages":[11],"order":1177,"sourceRefs":[{"index":2,"pages":[15,19]}]},{"id":"ox-outbreak-investigation-008","lecture":"outbreak-investigation","topic":"집락","statement":"질병집락은 시간·장소상 모여 있는 사례를 가리킨다.","answer":true,"explanation":"우연한 집합인지 공통 원인이 있는지 조사한다.","pages":[12],"order":1178,"sourceRefs":[{"index":2,"pages":[16]}]},{"id":"ox-outbreak-investigation-009","lecture":"outbreak-investigation","topic":"집락과 인과","statement":"질병집락을 발견하면 공통 감염원이 이미 확정된다.","answer":false,"explanation":"집락은 조사의 출발점이며 인과 확인이 필요하다.","pages":[12],"order":1179,"sourceRefs":[{"index":2,"pages":[16,19]}]},{"id":"ox-outbreak-investigation-010","lecture":"outbreak-investigation","topic":"유행 확인","statement":"유행조사 초기에 진단과 실제 환자 증가 여부를 확인한다.","answer":true,"explanation":"보고 변화·검사 변화에 의한 증가를 구분한다.","pages":[13,14],"order":1180,"sourceRefs":[{"index":2,"pages":[17,19]}]},{"id":"ox-outbreak-investigation-011","lecture":"outbreak-investigation","topic":"사례 정의","statement":"일관된 사례 정의는 환자를 같은 기준으로 찾는 데 중요하다.","answer":true,"explanation":"임상·시간·장소·사람 조건 등을 정한다.","pages":[14],"order":1181,"sourceRefs":[{"index":2,"pages":[19]}]},{"id":"ox-outbreak-investigation-012","lecture":"outbreak-investigation","topic":"사례 정의 오류","statement":"원인 음식이 의심되면 그 음식을 먹은 사람만 환자로 정의해야 공정한 비교가 된다.","answer":false,"explanation":"노출을 사례 정의에 넣으면 가설 검정이 편향될 수 있다.","pages":[14],"order":1182,"sourceRefs":[{"index":2,"pages":[19]}]},{"id":"ox-outbreak-investigation-013","lecture":"outbreak-investigation","topic":"발단 사례","statement":"처음 발견된 사례가 반드시 유행에서 가장 먼저 감염된 사람은 아니다.","answer":true,"explanation":"발단 사례와 일차 사례를 구분한다.","pages":[14],"order":1183,"sourceRefs":[{"index":2,"pages":[19]}]},{"id":"ox-outbreak-investigation-014","lecture":"outbreak-investigation","topic":"기술역학","statement":"기술역학에서는 시간·장소·사람에 따른 분포를 정리한다.","answer":true,"explanation":"원인 가설을 만드는 기초이다.","pages":[15],"order":1184,"sourceRefs":[{"index":2,"pages":[20]}]},{"id":"ox-outbreak-investigation-015","lecture":"outbreak-investigation","topic":"곡선 세로축","statement":"유행곡선의 세로축에는 보통 새로운 환자 수 대신 연령만 표시한다.","answer":false,"explanation":"발병 건수 또는 환자 수를 표시한다.","pages":[16],"order":1185,"sourceRefs":[{"index":2,"pages":[21]}]},{"id":"ox-outbreak-investigation-016","lecture":"outbreak-investigation","topic":"단일봉","statement":"짧은 기간의 공통 노출은 단일봉 유행곡선을 만들 수 있다.","answer":true,"explanation":"잠복기의 변동을 고려한다.","pages":[18],"order":1186,"sourceRefs":[{"index":2,"pages":[23]}]},{"id":"ox-outbreak-investigation-017","lecture":"outbreak-investigation","topic":"다봉형","statement":"봉우리가 여러 개인 유행곡선은 사람 간 전파만으로 확정된다.","answer":false,"explanation":"반복 노출·지속 노출 등도 가능하다.","pages":[19],"order":1187,"sourceRefs":[{"index":2,"pages":[23,24]}]},{"id":"ox-outbreak-investigation-018","lecture":"outbreak-investigation","topic":"잠복기 활용","statement":"유행곡선과 잠복기를 함께 보면 가능한 노출 기간을 추정할 수 있다.","answer":true,"explanation":"단순한 환자 총수보다 많은 정보를 준다.","pages":[16,18],"order":1188,"sourceRefs":[{"index":2,"pages":[21,23,24]}]},{"id":"ox-outbreak-investigation-019","lecture":"outbreak-investigation","topic":"점지도","statement":"점지도는 환자 위치와 의심 감염원 사이의 공간적 관계를 살펴보는 데 쓴다.","answer":true,"explanation":"공통 장소 노출 가설에 도움이 된다.","pages":[20],"order":1189,"sourceRefs":[{"index":2,"pages":[25]}]},{"id":"ox-outbreak-investigation-020","lecture":"outbreak-investigation","topic":"지도의 한계","statement":"환자가 많은 동네가 지도에 보이면 인구수와 무관하게 발생 위험이 가장 높다.","answer":false,"explanation":"인구 분모와 사람의 이동·노출을 고려해야 한다.","pages":[20],"order":1190,"sourceRefs":[{"index":2,"pages":[20,25]}]},{"id":"ox-outbreak-investigation-021","lecture":"outbreak-investigation","topic":"가설 설정","statement":"원인 가설은 병원체·감염원·전파 경로 등을 포함할 수 있다.","answer":true,"explanation":"기술역학과 면담 정보를 종합한다.","pages":[21],"order":1191,"sourceRefs":[{"index":2,"pages":[26]}]},{"id":"ox-outbreak-investigation-022","lecture":"outbreak-investigation","topic":"분석역학","statement":"분석역학 연구는 노출과 발병의 연관을 비교하는 데 사용한다.","answer":true,"explanation":"단순 사례 나열을 넘어선다.","pages":[22],"order":1192,"sourceRefs":[{"index":2,"pages":[27]}]},{"id":"ox-outbreak-investigation-023","lecture":"outbreak-investigation","topic":"코호트 설계","statement":"명단과 노출 정보가 있는 연회 참석자 집단에서는 후향적 코호트를 사용할 수 없다.","answer":false,"explanation":"노출별 발병률 비교에 적합할 수 있다.","pages":[23],"order":1193,"sourceRefs":[{"index":2,"pages":[27,28]}]},{"id":"ox-outbreak-investigation-024","lecture":"outbreak-investigation","topic":"발병률 비교","statement":"노출군과 비노출군의 발병률 비는 상대위험도 계산의 기본이다.","answer":true,"explanation":"각 집단의 발병자와 비발병자를 확인한다.","pages":[23],"order":1194,"sourceRefs":[{"index":2,"pages":[28]}]},{"id":"ox-outbreak-investigation-025","lecture":"outbreak-investigation","topic":"위험도 계산","statement":"음식을 먹은 환자 수만 많으면 섭취자 전체 수를 몰라도 그 음식의 상대위험도를 계산한다.","answer":false,"explanation":"노출·비노출 집단의 분모가 필요하다.","pages":[23],"order":1195,"sourceRefs":[{"index":2,"pages":[28]}]},{"id":"ox-outbreak-investigation-026","lecture":"outbreak-investigation","topic":"환자대조군","statement":"환자-대조군 연구에서는 과거 노출의 오즈를 비교할 수 있다.","answer":true,"explanation":"질병 상태로 대상을 선택한다.","pages":[24],"order":1196,"sourceRefs":[{"index":2,"pages":[27,29]}],"note":"AI 보충·정정: 역학조사 PDF29쪽 원표의 해산물 회 OR은 (7×24)/(2×12)=7입니다. 같은 쪽 주석의 다른 음식·수치와 섞지 않고 제시된 표에서 계산합니다."},{"id":"ox-outbreak-investigation-027","lecture":"outbreak-investigation","topic":"대조군 선택","statement":"환자-대조군 연구의 대조군은 반드시 노출되지 않은 사람만 골라야 한다.","answer":false,"explanation":"환자가 나온 근원 집단을 대표하도록 선정한다.","pages":[24],"order":1197,"sourceRefs":[{"index":2,"pages":[29]}]},{"id":"ox-outbreak-investigation-028","lecture":"outbreak-investigation","topic":"관리 시점","statement":"충분히 의심되는 위험이 있으면 조사를 진행하면서 관리 조치를 시행할 수 있다.","answer":true,"explanation":"모든 분석이 끝날 때까지 전파 차단을 미루지 않는다.","pages":[25],"order":1198,"sourceRefs":[{"index":2,"pages":[30]}]},{"id":"ox-outbreak-investigation-029","lecture":"outbreak-investigation","topic":"평가","statement":"유행 관리 조치는 시행만 하면 효과 평가가 필요 없다.","answer":false,"explanation":"추가 환자와 노출 감소 등을 확인한다.","pages":[25],"order":1199,"sourceRefs":[{"index":2,"pages":[30]}]},{"id":"ox-outbreak-investigation-030","lecture":"outbreak-investigation","topic":"조사의 연결","statement":"사례 확인·기술역학·가설·검정·관리 평가는 서로 연결된다.","answer":true,"explanation":"현장에서는 일부 단계가 동시에 진행될 수 있다.","pages":[26],"order":1200,"sourceRefs":[{"index":2,"pages":[17,18,30,31]}]},{"id":"ox-prevention-001","lecture":"prevention","topic":"일차 예방","statement":"질병이 생기기 전에 감염이나 발병을 줄이는 조치는 일차 예방에 포함된다.","answer":true,"explanation":"예방접종이 대표적이다.","pages":[2],"order":1201,"sourceRefs":[{"index":2,"pages":[5]}]},{"id":"ox-prevention-002","lecture":"prevention","topic":"이차 예방","statement":"조기 발견과 치료는 원칙적으로 삼차 예방에만 해당한다.","answer":false,"explanation":"조기 진단·치료는 이차 예방과 관련된다.","pages":[2],"order":1202,"sourceRefs":[{"index":2,"pages":[5]}]},{"id":"ox-prevention-003","lecture":"prevention","topic":"예방 결정","statement":"감염병 예방은 병원체·숙주·환경과 전파 경로를 고려한다.","answer":true,"explanation":"증상이 비슷해도 조치가 다를 수 있다.","pages":[3,4],"order":1203,"sourceRefs":[{"index":2,"pages":[7,8,9,10]}]},{"id":"ox-prevention-004","lecture":"prevention","topic":"같은 기침","statement":"모두 기침을 하므로 결핵과 백일해는 같은 주의 조치만 적용한다.","answer":false,"explanation":"전파 경로와 감염관리가 다르다.","pages":[5,6],"order":1204,"sourceRefs":[{"index":2,"pages":[8,9,10,11]}]},{"id":"ox-prevention-005","lecture":"prevention","topic":"공기주의","statement":"전염성 폐결핵에는 공기주의가 중요하다.","answer":true,"explanation":"적절한 호흡기 보호와 환기 등을 적용한다.","pages":[7,8],"order":1205,"sourceRefs":[{"index":2,"pages":[3,9,10,11]}],"note":"필기본 강조: 예방원칙 PDF3·11쪽의 다제내성 폐결핵도 표준주의에 공기주의를 추가합니다. 내성 여부가 전파경로를 접촉전파로 바꾸지는 않습니다."},{"id":"ox-prevention-006","lecture":"prevention","topic":"접촉주의","statement":"접촉 전파 병원체에는 손 위생과 접촉주의가 중요하다.","answer":true,"explanation":"병원체별 추가 주의를 적용한다.","pages":[7],"order":1206,"sourceRefs":[{"index":2,"pages":[9,10]}]},{"id":"ox-prevention-007","lecture":"prevention","topic":"PEP 시점","statement":"노출 후 예방은 감염병 증상이 생긴 뒤에만 시작한다.","answer":false,"explanation":"증상 전 적절한 시간 안에 위험을 줄이는 목적이다.","pages":[9],"order":1207,"sourceRefs":[{"index":2,"pages":[12]}]},{"id":"ox-prevention-008","lecture":"prevention","topic":"접촉자 평가","statement":"노출 후 예방은 접촉 종류와 숙주 면역을 평가해 결정한다.","answer":true,"explanation":"같은 공간에 있었다고 모두 같은 위험은 아니다.","pages":[9,10],"order":1208,"sourceRefs":[{"index":2,"pages":[7,12,19,22]}]},{"id":"ox-prevention-009","lecture":"prevention","topic":"사슬알균 치료 목적","statement":"A군 사슬알균 인두염의 항생제는 통증 완화 외에는 목적이 없다.","answer":false,"explanation":"류마티스열 예방과 전파 감소도 목적이다.","pages":[11,12],"order":1209,"sourceRefs":[{"index":2,"pages":[15,16]}]},{"id":"ox-prevention-010","lecture":"prevention","topic":"류마티스열 예방","statement":"사슬알균 인두염 치료는 급성 류마티스열의 일차 예방에 해당할 수 있다.","answer":true,"explanation":"재발 방지를 위한 이차 예방과 구별한다.","pages":[13],"order":1210,"sourceRefs":[{"index":2,"pages":[15,16]}]},{"id":"ox-prevention-011","lecture":"prevention","topic":"재발 예방","statement":"류마티스열 병력이 있는 사람의 재발 예방은 과거 병력과 무관하다.","answer":false,"explanation":"이차 예방의 적응증·기간을 따로 평가한다.","pages":[13],"order":1211,"sourceRefs":[{"index":2,"pages":[16]}]},{"id":"ox-prevention-012","lecture":"prevention","topic":"수두 면역","statement":"VZV 노출 후에는 수두 병력·접종력 등 면역의 근거를 확인한다.","answer":true,"explanation":"면역 여부에 따라 후속 조치가 달라진다.","pages":[15,16],"order":1212,"sourceRefs":[{"index":2,"pages":[19]}]},{"id":"ox-prevention-013","lecture":"prevention","topic":"대상포진 전파","statement":"수두 면역이 없는 사람이 대상포진 병변에 노출되면 반드시 대상포진으로 발병한다.","answer":false,"explanation":"감염되면 초감염인 수두가 발생할 수 있다.","pages":[15,16],"order":1213,"sourceRefs":[{"index":2,"pages":[17,18,19]}]},{"id":"ox-prevention-014","lecture":"prevention","topic":"고위험 VZV 노출","statement":"수두 면역이 없는 임신부·면역저하자는 노출 후 별도 평가가 필요하다.","answer":true,"explanation":"생백신 가능 여부와 수동면역 등을 구분한다.","pages":[16],"order":1214,"sourceRefs":[{"index":2,"pages":[19]}],"note":"AI 보충·정정: PDF19의 VZIG 4–10일 요약을 4일까지 기다리라는 뜻으로 읽지 않습니다. 적응증이면 가능한 한 빨리, 노출 후10일 이내 투여하며 고위험 조건을 따로 확인합니다.","references":[{"label":"CDC · 중증 수두 위험군과 노출 후 VariZIG","url":"https://www.cdc.gov/chickenpox/hcp/clinical-guidance/index.html"}]},{"id":"ox-prevention-015","lecture":"prevention","topic":"임신부 수두백신","statement":"비면역 임신부는 노출 후 수두 생백신을 일률적으로 즉시 접종한다.","answer":false,"explanation":"임신 중 생백신은 피하고 적절한 노출 후 조치를 평가한다.","pages":[16],"order":1215,"sourceRefs":[{"index":2,"pages":[19]}]},{"id":"ox-prevention-016","lecture":"prevention","topic":"혈액매개","statement":"혈액 노출에서는 HBV·HCV·HIV 등을 고려한다.","answer":true,"explanation":"점막·피부 손상·주사침 노출을 구분한다.","pages":[17],"order":1216,"sourceRefs":[{"index":2,"pages":[20,21]}]},{"id":"ox-prevention-017","lecture":"prevention","topic":"주사침 초기 평가","statement":"주사침 사고 후에는 노출원과 노출자의 상태를 함께 확인한다.","answer":true,"explanation":"예방 조치와 추적검사의 기준이 된다.","pages":[18,19],"order":1217,"sourceRefs":[{"index":2,"pages":[20,21,22,23]}]},{"id":"ox-prevention-018","lecture":"prevention","topic":"HIV PEP 지연","statement":"HIV 노출 후 예방은 효과를 높이기 위해 며칠 기다렸다 시작한다.","answer":false,"explanation":"적응증이면 가능한 한 빨리 시작한다.","pages":[19],"order":1218,"sourceRefs":[{"index":2,"pages":[20,27]}]},{"id":"ox-prevention-019","lecture":"prevention","topic":"HBV 면역","statement":"HBV 노출 후 예방은 접종력과 항체 반응에 따라 달라진다.","answer":true,"explanation":"모든 노출자에게 같은 조합을 쓰지 않는다.","pages":[19,20],"order":1219,"sourceRefs":[{"index":2,"pages":[21,22,23]}]},{"id":"ox-prevention-020","lecture":"prevention","topic":"HCV 백신","statement":"HCV 주사침 노출은 백신을 즉시 접종하면 해결된다.","answer":false,"explanation":"표준 HCV 백신은 없어 검사·추적과 필요시 치료가 중요하다.","pages":[17,19],"order":1220,"sourceRefs":[{"index":2,"pages":[20]}]},{"id":"ox-prevention-021","lecture":"prevention","topic":"PrEP","statement":"PrEP는 HIV 감염 위험이 있는 사람의 노출 전 예방이다.","answer":true,"explanation":"노출 후 예방인 PEP와 구분한다.","pages":[24,25],"order":1221,"sourceRefs":[{"index":2,"pages":[6,24,25,26,27,28]}]},{"id":"ox-prevention-022","lecture":"prevention","topic":"예방과 치료","statement":"산모의 HIV 관리와 신생아 예방은 수직 전파 감소에 기여하지 못한다.","answer":false,"explanation":"적절한 치료·예방 전략으로 위험을 줄일 수 있다.","pages":[24],"order":1222,"sourceRefs":[{"index":2,"pages":[24,25,26,27,28]}]},{"id":"ox-prevention-023","lecture":"prevention","topic":"수술 위험도","statement":"수술 부위의 오염 정도는 수술부위감염 위험 평가에 중요하다.","answer":true,"explanation":"청결·청결오염·오염 등으로 구분한다.","pages":[27],"order":1223,"sourceRefs":[{"index":2,"pages":[30]}]},{"id":"ox-prevention-024","lecture":"prevention","topic":"수술 예방약","statement":"모든 수술에는 같은 광범위 항생제를 같은 기간 쓴다.","answer":false,"explanation":"예상 균·수술 종류·환자 요인에 맞춘다.","pages":[28,29],"order":1224,"sourceRefs":[{"index":2,"pages":[31,32,33,34,35]}]},{"id":"ox-prevention-025","lecture":"prevention","topic":"피부 균총","statement":"청결 수술의 예방약 선택에서는 피부 상재균을 고려한다.","answer":true,"explanation":"수술 부위의 예상 병원체를 겨냥한다.","pages":[29,30],"order":1225,"sourceRefs":[{"index":2,"pages":[32,33]}]},{"id":"ox-prevention-026","lecture":"prevention","topic":"투여 시점","statement":"수술 예방 항생제는 오염이 생기기 전 적절한 조직 농도를 확보하는 것이 중요하다.","answer":true,"explanation":"절개 전 투여 시점을 조정한다.","pages":[31],"order":1226,"sourceRefs":[{"index":2,"pages":[31,34]}]},{"id":"ox-prevention-027","lecture":"prevention","topic":"예방약 시점","statement":"수술 예방약은 절개가 끝난 뒤 처음 투여하는 것이 원칙이다.","answer":false,"explanation":"절개 시점에 효과적인 농도가 있어야 한다.","pages":[31],"order":1227,"sourceRefs":[{"index":2,"pages":[34]}]},{"id":"ox-prevention-028","lecture":"prevention","topic":"추가 투여","statement":"긴 수술이나 대량 출혈에서는 예방 항생제의 추가 투여를 고려할 수 있다.","answer":true,"explanation":"약물 반감기와 혈중 농도를 고려한다.","pages":[31],"order":1228,"sourceRefs":[{"index":2,"pages":[31,34]}]},{"id":"ox-prevention-029","lecture":"prevention","topic":"장기 예방약","statement":"수술 후 예방 항생제는 오래 줄수록 항상 감염이 더 잘 예방된다.","answer":false,"explanation":"불필요한 연장은 부작용·내성 등 손해를 늘릴 수 있다.","pages":[32],"order":1229,"sourceRefs":[{"index":2,"pages":[35]}]},{"id":"ox-prevention-030","lecture":"prevention","topic":"목적 구분","statement":"예방적 항생제와 이미 발생한 감염의 치료는 목적과 기간이 다르다.","answer":true,"explanation":"같은 기준을 그대로 적용하지 않는다.","pages":[32],"order":1230,"sourceRefs":[{"index":2,"pages":[30,31,35]}]},{"id":"ox-environmental-control-001","lecture":"environmental-control","topic":"세척","statement":"세척은 오염물과 유기물을 물리적으로 제거하는 과정이다.","answer":true,"explanation":"소독·멸균 효과를 높이는 선행 단계이다.","pages":[4,5],"order":1231,"sourceRefs":[{"index":2,"pages":[8]}]},{"id":"ox-environmental-control-002","lecture":"environmental-control","topic":"처리 순서","statement":"유기물이 많이 묻은 기구는 세척 없이 바로 소독하면 항상 같은 효과를 얻는다.","answer":false,"explanation":"유기물이 약제 작용을 방해할 수 있다.","pages":[5],"order":1232,"sourceRefs":[{"index":2,"pages":[8]}]},{"id":"ox-environmental-control-003","lecture":"environmental-control","topic":"멸균","statement":"멸균은 아포를 포함한 모든 미생물의 제거·불활성화를 목표로 한다.","answer":true,"explanation":"일반적인 소독과 구분한다.","pages":[4],"order":1233,"sourceRefs":[{"index":2,"pages":[8,9]}]},{"id":"ox-environmental-control-004","lecture":"environmental-control","topic":"높은 수준 소독","statement":"높은 수준 소독은 어떤 조건에서도 모든 세균 아포의 완전 제거를 보장한다.","answer":false,"explanation":"아포가 남을 수 있어 멸균과 다르다.","pages":[6],"order":1234,"sourceRefs":[{"index":2,"pages":[9,19]}]},{"id":"ox-environmental-control-005","lecture":"environmental-control","topic":"저항성","statement":"미생물은 구조에 따라 소독제 저항성이 다르다.","answer":true,"explanation":"외피·아포 등 특성이 영향을 준다.","pages":[7],"order":1235,"sourceRefs":[{"index":2,"pages":[10,24]}]},{"id":"ox-environmental-control-006","lecture":"environmental-control","topic":"외피 저항성","statement":"외피 바이러스는 일반적으로 비외피 바이러스보다 소독에 항상 더 강하다.","answer":false,"explanation":"대개 지질 외피가 있어 소독에 더 민감하다.","pages":[7],"order":1236,"sourceRefs":[{"index":2,"pages":[10,24]}]},{"id":"ox-environmental-control-007","lecture":"environmental-control","topic":"알코올","statement":"알코올은 단백질 변성 등으로 미생물을 불활성화한다.","answer":true,"explanation":"적절한 농도와 접촉 시간이 중요하다.","pages":[9],"order":1237,"sourceRefs":[{"index":2,"pages":[12]}]},{"id":"ox-environmental-control-008","lecture":"environmental-control","topic":"알코올 아포","statement":"알코올 손소독제는 세균 아포를 확실히 제거하는 멸균제이다.","answer":false,"explanation":"아포에 효과가 제한된다.","pages":[9],"order":1238,"sourceRefs":[{"index":2,"pages":[12]}]},{"id":"ox-environmental-control-009","lecture":"environmental-control","topic":"Chlorhexidine","statement":"클로르헥시딘은 피부 소독에 사용되며 잔류 효과가 있다.","answer":true,"explanation":"사용 부위·제형·농도를 확인한다.","pages":[10,12],"order":1239,"sourceRefs":[{"index":2,"pages":[13,14,15]}]},{"id":"ox-environmental-control-010","lecture":"environmental-control","topic":"인체 적용","statement":"피부 소독제는 눈·중이·점막 등 어느 부위에나 같은 농도로 써도 된다.","answer":false,"explanation":"조직 독성과 허가된 용도를 확인해야 한다.","pages":[12],"order":1240,"sourceRefs":[{"index":2,"pages":[13,14,15]}]},{"id":"ox-environmental-control-011","lecture":"environmental-control","topic":"혈액배양","statement":"혈액배양 전 적절한 피부 소독은 오염률을 줄인다.","answer":true,"explanation":"불필요한 치료와 재검사를 줄이는 데 도움 된다.","pages":[13],"order":1241,"sourceRefs":[{"index":2,"pages":[16,49]}],"note":"필기본 강조: 환경관리 PDF49쪽은 예상문제 슬라이드입니다. 3% 이하 기준과 1%도 달성 가능한 개선 목표, 완전 건조·재접촉 방지·병마개 소독·오염률 피드백을 함께 확인하세요."},{"id":"ox-environmental-control-012","lecture":"environmental-control","topic":"고위험 기구","statement":"혈관이나 무균 조직에 들어가는 고위험 기구는 멸균이 원칙이다.","answer":true,"explanation":"기구가 닿는 부위로 위험을 분류한다.","pages":[15,18],"order":1242,"sourceRefs":[{"index":2,"pages":[18,21]}]},{"id":"ox-environmental-control-013","lecture":"environmental-control","topic":"준위험 기구","statement":"점막에 닿는 준위험 기구는 간단히 물로 헹구기만 하면 된다.","answer":false,"explanation":"보통 높은 수준 소독 이상이 필요하다.","pages":[16],"order":1243,"sourceRefs":[{"index":2,"pages":[19,21]}]},{"id":"ox-environmental-control-014","lecture":"environmental-control","topic":"비위험 기구","statement":"손상 없는 피부에만 닿는 기구는 비위험 기구로 분류한다.","answer":true,"explanation":"오염 정도에 맞는 세척·소독을 시행한다.","pages":[17],"order":1244,"sourceRefs":[{"index":2,"pages":[20,21]}],"note":"필기본 정정 반영: PDF21쪽 경피시술용 외부 초음파 프로브 설명에는 일회용 멸균 커버 조건이 추가되어 있습니다. 시술의 무균 수준에 맞는 커버와 재처리를 함께 적용하며, 실제 무균조직에 들어가는 재사용 기구의 멸균을 생략한다는 뜻은 아닙니다.","references":[{"label":"AIUM 2025 · 초음파 프로브 재처리와 일회용 커버","url":"https://www.aium.org/resources/official-statements/view/guidelines-for-cleaning-and-preparing-external--and-internal-use-ultrasound-transducers-and-equipment-between-patients-as-well-as-safe-handling-and-use-of-ultrasound-coupling-gel"}]},{"id":"ox-environmental-control-015","lecture":"environmental-control","topic":"기구 분류","statement":"Spaulding 분류는 기구 가격만을 기준으로 한다.","answer":false,"explanation":"접촉하는 조직과 감염 위험이 기준이다.","pages":[18],"order":1245,"sourceRefs":[{"index":2,"pages":[18,19,20,21]}]},{"id":"ox-environmental-control-016","lecture":"environmental-control","topic":"알데히드","statement":"글루타르알데히드는 높은 수준 소독 등에 사용될 수 있다.","answer":true,"explanation":"농도·시간·환기와 잔류 처리가 중요하다.","pages":[23],"order":1246,"sourceRefs":[{"index":2,"pages":[26]}]},{"id":"ox-environmental-control-017","lecture":"environmental-control","topic":"잔류 독성","statement":"기구 소독제는 강할수록 인체에 잔류해도 무해하다.","answer":false,"explanation":"독성과 잔류물을 관리해야 한다.","pages":[23],"order":1247,"sourceRefs":[{"index":2,"pages":[19,26]}]},{"id":"ox-environmental-control-018","lecture":"environmental-control","topic":"염소계","statement":"염소계 소독제의 효과는 농도와 접촉 시간·유기물의 영향을 받는다.","answer":true,"explanation":"목적별 사용 지침을 따른다.","pages":[24],"order":1248,"sourceRefs":[{"index":2,"pages":[27,40]}]},{"id":"ox-environmental-control-019","lecture":"environmental-control","topic":"혼합 사용","statement":"염소계 소독제는 산성 세제와 임의로 섞으면 더 안전하다.","answer":false,"explanation":"유해 가스 위험이 있어 임의 혼합하지 않는다.","pages":[24],"order":1249,"sourceRefs":[{"index":2,"pages":[27]}]},{"id":"ox-environmental-control-020","lecture":"environmental-control","topic":"산화제","statement":"과산화수소와 과초산은 산화 작용을 이용하는 소독제이다.","answer":true,"explanation":"허가된 적용 조건을 확인한다.","pages":[25],"order":1250,"sourceRefs":[{"index":2,"pages":[28]}]},{"id":"ox-environmental-control-021","lecture":"environmental-control","topic":"고압증기","statement":"고압증기멸균은 습열을 이용하는 방법이다.","answer":true,"explanation":"기구의 내열성과 포장을 고려한다.","pages":[27],"order":1251,"sourceRefs":[{"index":2,"pages":[30]}]},{"id":"ox-environmental-control-022","lecture":"environmental-control","topic":"열 민감 기구","statement":"열에 약한 모든 기구도 고압증기로만 멸균해야 한다.","answer":false,"explanation":"재질에 맞는 저온 멸균법 등을 선택한다.","pages":[27],"order":1252,"sourceRefs":[{"index":2,"pages":[18,19,30]}]},{"id":"ox-environmental-control-023","lecture":"environmental-control","topic":"멸균 확인","statement":"멸균 확인에는 물리적·화학적·생물학적 지시자를 활용한다.","answer":true,"explanation":"서로 확인하는 내용과 한계가 다르다.","pages":[30],"order":1253,"sourceRefs":[{"index":2,"pages":[35]}]},{"id":"ox-environmental-control-024","lecture":"environmental-control","topic":"화학 지시자","statement":"포장지의 화학 지시자 색 변화만으로 모든 기구의 완전 멸균이 확정된다.","answer":false,"explanation":"공정 조건 노출 표시와 무균 보장은 다르다.","pages":[30],"order":1254,"sourceRefs":[{"index":2,"pages":[35]}]},{"id":"ox-environmental-control-025","lecture":"environmental-control","topic":"HEPA","statement":"HEPA 필터는 공기 중 입자 관리를 위한 장치이다.","answer":true,"explanation":"표면 소독제와 역할이 다르다.","pages":[31],"order":1255,"sourceRefs":[{"index":2,"pages":[36]}]},{"id":"ox-environmental-control-026","lecture":"environmental-control","topic":"4급암모늄","statement":"4급암모늄제는 프리온과 아포에 대한 일상적 멸균제로 쓰인다.","answer":false,"explanation":"일반 환경의 낮은 수준 소독에 주로 사용한다.","pages":[33,34],"order":1256,"sourceRefs":[{"index":2,"pages":[37,38,39]}]},{"id":"ox-environmental-control-027","lecture":"environmental-control","topic":"접촉 시간","statement":"소독제는 표면에 필요한 접촉 시간을 확보해야 한다.","answer":true,"explanation":"바른 뒤 곧바로 닦아내면 효과가 부족할 수 있다.","pages":[35],"order":1257,"sourceRefs":[{"index":2,"pages":[40]}]},{"id":"ox-environmental-control-028","lecture":"environmental-control","topic":"C. difficile","statement":"C. difficile 병실은 일반 알코올만으로 아포 관리가 충분하다.","answer":false,"explanation":"아포에 적합한 환경 소독과 손 위생 원칙이 필요하다.","pages":[36],"order":1258,"sourceRefs":[{"index":2,"pages":[41,48]}],"note":"필기본 강조: PDF48쪽의 CDI 관리 묶음에는 물·비누 손세척, 전용기구, 설사 소실 후 최소48시간 접촉주의와 아포 소독이 포함됩니다. 강의의 염소계 예시는5,000ppm이며 실제 적용은 제품·기관 지침을 따릅니다.","references":[{"label":"CDC · CDI 접촉주의와 아포 환경소독","url":"https://www.cdc.gov/c-diff/hcp/clinical-guidance/index.html"}]},{"id":"ox-environmental-control-029","lecture":"environmental-control","topic":"노로바이러스","statement":"노로바이러스는 비외피 바이러스에 맞는 소독 전략이 필요하다.","answer":true,"explanation":"구토물·분변 오염을 적절히 처리한다.","pages":[37],"order":1259,"sourceRefs":[{"index":2,"pages":[42]}]},{"id":"ox-environmental-control-030","lecture":"environmental-control","topic":"Candida auris","statement":"Candida auris는 환경 지속성과 의료기관 전파 관리가 중요하다.","answer":true,"explanation":"검증된 제품과 청소·소독 원칙을 적용한다.","pages":[38],"order":1260,"sourceRefs":[{"index":2,"pages":[39,43,44]}]},{"id":"ox-cbl-1-001","lecture":"cbl-1","topic":"간농양","statement":"당뇨병 환자의 간농양과 시력 저하는 침습성 K. pneumoniae 감염을 떠올리게 한다.","answer":true,"explanation":"혈행성 전이 감염을 함께 평가한다.","pages":[2,3],"order":1261,"guideId":"cbl-1-case-1","references":[{"label":"Russo et al., J Clin Microbiol 2018 · 고병원성 K. pneumoniae 표지자 원저","url":"https://pubmed.ncbi.nlm.nih.gov/29925642/"}],"note":"필기본의 단정·오타를 보완한 내용은 연결된 증례 해설의 AI 보충·정정과 아래 근거를 함께 확인하세요."},{"id":"ox-cbl-1-002","lecture":"cbl-1","topic":"안내염","statement":"간농양 환자의 눈 통증은 간 감염과 항상 무관하다.","answer":false,"explanation":"혈행성 내인성 안내염일 수 있다.","pages":[2,3],"order":1262,"guideId":"cbl-1-case-1","references":[{"label":"Russo et al., J Clin Microbiol 2018 · 고병원성 K. pneumoniae 표지자 원저","url":"https://pubmed.ncbi.nlm.nih.gov/29925642/"}],"note":"필기본의 단정·오타를 보완한 내용은 연결된 증례 해설의 AI 보충·정정과 아래 근거를 함께 확인하세요."},{"id":"ox-cbl-1-003","lecture":"cbl-1","topic":"String test","statement":"양성 string test는 고점액성 표현형의 단서이다.","answer":true,"explanation":"고병원성이나 내성을 단독으로 확정하지는 않는다.","pages":[3],"order":1263,"guideId":"cbl-1-case-1","references":[{"label":"Russo et al., J Clin Microbiol 2018 · 고병원성 K. pneumoniae 표지자 원저","url":"https://pubmed.ncbi.nlm.nih.gov/29925642/"}],"note":"필기본의 단정·오타를 보완한 내용은 연결된 증례 해설의 AI 보충·정정과 아래 근거를 함께 확인하세요."},{"id":"ox-cbl-1-004","lecture":"cbl-1","topic":"독력과 내성","statement":"고점액성 클렙시엘라는 반드시 모든 항생제에 내성이다.","answer":false,"explanation":"점액성·독력·내성은 서로 다른 성질이다.","pages":[3],"order":1264,"guideId":"cbl-1-case-1","references":[{"label":"Russo et al., J Clin Microbiol 2018 · 고병원성 K. pneumoniae 표지자 원저","url":"https://pubmed.ncbi.nlm.nih.gov/29925642/"}],"note":"필기본의 단정·오타를 보완한 내용은 연결된 증례 해설의 AI 보충·정정과 아래 근거를 함께 확인하세요."}];
